/*******************************************************************************
 * Script: seed_DimCourseAssessment_dev_testset.sql   (DEV ONLY)
 * Purpose: Course-scoped entry mapping for the synthetic ingest TEST SET
 *          (generated by data/imports/_generate_ingest_testset.ps1). Every
 *          MAT-* -> Math (Language NULL); ELA-* -> English Literacy;
 *          FLA-* -> French Literacy. Idempotent: clears then re-seeds.
 *          Run on DEV after ingesting the test set so entry resolves courses.
 * Region: Canada East (PIIDPA compliant)
 ******************************************************************************/

DELETE FROM DimCourseAssessment;


SELECT Language, Kind, COUNT(*) AS Courses FROM DimCourseAssessment GROUP BY Language, Kind ORDER BY Kind, Language;